// Generated by scripts/sync-help.mjs from pzza-code-web/components/home/TasksPanel.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * The Tasks dropdown showing one race of 3 agents, ported from the app's
 * TaskDetail and LandSummary (src/tasks/TaskDetail.tsx, TaskLand.tsx) and
 * styled by the app's own stylesheet (app.css). A race is compared and landed
 * in the task window, so the dropdown shows the task, one line per attempt
 * and Open details.
 * While the scene is on screen it plays the race: the three attempts work
 * (live dots, their diffs growing) and stop one by one. Any click or keystroke
 * in the scene stops the loop and hands the panel over.
 */
import { useRef, useState } from "react";
import { ArrowLeft, Crosshair, FolderGit2, GitBranch, Monitor } from "lucide-react";
import { AgentMark, agentLabel } from "./AppUI";
import type { AgentId } from "./agents";
import { useScenePlayback, useVisitorTakeover, type Wait } from "./playback";

type Phase = "review" | "working";

interface Attempt {
  agent: AgentId;
  /** The attempt's session and worktree name, as the app names repeats of one agent. */
  session: string;
  phase: Phase;
  reason: string;
  added: number;
  removed: number;
}

const TASK = {
  title: "Add search to the notes page",
  repo: "web",
  base: "main",
  slug: "add-search-to-the-notes-page",
};

// Three Claude Code attempts, as they finished: each edited the notes list in
// its own worktree (git diff --numstat).
const ATTEMPTS: Attempt[] = [
  { added: 25, removed: 1 },
  { added: 28, removed: 1 },
  { added: 22, removed: 1 },
].map((lines, i) => ({ agent: "claude", session: `${TASK.slug}-claude-${i + 1}`, phase: "review", reason: "Ready for review", ...lines }));

/** The app's StatusDot (src/tasks/TaskParts.tsx); it pulses while the agent works. */
function StatusDot({ tone, live }: { tone: Phase; live?: boolean }) {
  return <span className={`usage-dot task-tone-${tone} ${live ? "task-dot-live" : ""}`} aria-hidden="true" />;
}

/** The app's DiffStat without a file count, as an attempt line shows it. */
function DiffStat({ added, removed }: { added: number; removed: number }) {
  return (
    <span className="task-diffstat" aria-label={`${added} lines added, ${removed} removed`}>
      <span className="task-add">+{added}</span>
      <span className="task-del">−{removed}</span>
    </span>
  );
}

/* The loop: the race starts with all three attempts working; each stops at
   its own tick (the third first), and the settled race is the page's frame. */
const RACE_TICK_MS = 850;
const SETTLE_TICK = [6, 7, 5];
// Share of its final diff an attempt has written when the loop picks it up.
const RACE_START_SHARE = 0.35;
const HOLD_SETTLED_MS = 4200;

/** Attempt `i` at `tick`: working with part of its diff written, or as it finished. */
function attemptAt(attempt: Attempt, i: number, tick: number): Attempt {
  const settle = SETTLE_TICK[i];
  if (tick >= settle) return attempt;
  const share = RACE_START_SHARE + ((1 - RACE_START_SHARE) * tick) / settle;
  return { ...attempt, phase: "working", reason: "Working", added: Math.round(attempt.added * share) };
}

export function TasksPanel({ right, top }: { right: number; top: number }) {
  // The race tick while the loop plays it; null shows the settled race.
  const [tick, setTick] = useState<number | null>(null);
  const root = useRef<HTMLDivElement>(null);
  const handedOver = useVisitorTakeover(root);
  const attempts = tick === null ? ATTEMPTS : ATTEMPTS.map((item, i) => attemptAt(item, i, tick));
  // The task's column: working while any attempt works, else in review.
  const racing = attempts.some((item) => item.phase === "working");

  useScenePlayback(
    root,
    async (wait: Wait) => {
      await wait(HOLD_SETTLED_MS);
      for (let next = 0; next < Math.max(...SETTLE_TICK); next += 1) {
        setTick(next);
        await wait(RACE_TICK_MS);
      }
      setTick(null);
    },
    // Stopped mid-race, the attempts settle where the visitor can see them.
    { stopped: handedOver, onStop: () => setTick(null) },
  );

  return (
    <div ref={root} className="menu menu-panel notifications-panel tasks-menu-panel" style={{ right, top, left: "auto", width: 380 }}>
      <div className="menu-body latest-notifications tasks-panel">
        <section className="task-step" aria-label={`Task: ${TASK.title}`}>
          <div className="notification-actions menu-head tasks-head">
            <span className="menu-head-title tasks-title">Task · Race of {ATTEMPTS.length}</span>
            <div className="tasks-head-tools">
              <button type="button" className="icon-btn tasks-back" aria-label="Focus tile" title="Focus tile">
                <Crosshair size={14} aria-hidden="true" />
              </button>
              <button type="button" className="icon-btn tasks-back" aria-label="Back" title="Back (Esc)">
                <ArrowLeft size={15} aria-hidden="true" />
              </button>
            </div>
          </div>
          <button type="button" className="task-title" title="Rename">
            {TASK.title}
          </button>
          <div className="task-meta">
            <span className="task-phase">
              <StatusDot tone={racing ? "working" : "review"} live={racing} />
              {racing ? "Working" : "Review"}
            </span>
            <span className="task-meta-item" title={`~/fieldnotes/${TASK.repo}`}>
              <FolderGit2 size={12} aria-hidden="true" />
              {TASK.repo}
            </span>
            <span className="task-meta-item" title={`Started from ${TASK.base}`}>
              <GitBranch size={12} aria-hidden="true" />
              {TASK.base}
            </span>
            <span className="task-meta-item">
              <Monitor size={12} aria-hidden="true" />
              This Device
            </span>
          </div>
          <ul className="task-attempt-lines" aria-label="Attempts">
            {attempts.map((item) => (
              <li key={item.session}>
                <StatusDot tone={item.phase} live={item.phase === "working"} />
                <span className="usage-brand">
                  <AgentMark agent={item.agent} size={12} />
                </span>
                <span className="task-attempt-name">{agentLabel(item.agent)}</span>
                {item.added || item.removed ? <DiffStat added={item.added} removed={item.removed} /> : <span className="muted">{item.reason}</span>}
              </li>
            ))}
          </ul>
          <div className="task-land" role="group" aria-label="Land">
            <div className="task-actions usage-footer">
              <span />
              <button type="button" className="btn btn-sm">
                Open details
              </button>
            </div>
          </div>
        </section>
      </div>
    </div>
  );
}
